import path from "node:path"
import { fileURLToPath } from "node:url"
import base from "../../apps/site-web/vite.config"

const previewDir = path.dirname(fileURLToPath(import.meta.url))
const appDir = path.resolve(previewDir, "../../apps/site-web")
const repositoryDir = path.resolve(appDir, "../..")
const previewEntry = path.resolve(previewDir, "main.tsx").replaceAll("\\", "/")
const previewPlugin = {
  name: "m80-setup-preview",
  configureServer(server: { middlewares: { use: (handler: (request: { url?: string }, response: { statusCode: number; setHeader: (name: string, value: string) => void; end: (value: string) => void }, next: () => void) => void) => void } }) {
    server.middlewares.use((request, response, next) => {
      if (request.url !== "/m80-preview/" && request.url !== "/m80-preview") return next()
      response.statusCode = 200
      response.setHeader("content-type", "text/html; charset=utf-8")
      response.end(`<!doctype html><html lang="en" style="background:#0b0c0d"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>M80 Scope 1 setup mock preview</title><script type="module">import RefreshRuntime from "/@react-refresh";RefreshRuntime.injectIntoGlobalHook(window);window.$RefreshReg$=()=>{};window.$RefreshSig$=()=>type=>type;window.__vite_plugin_react_preamble_installed__=true;</script></head><body><div id="root"></div><script type="module" src="/@fs/${previewEntry}"></script></body></html>`)
    })
  },
}

export default {
  ...base,
  root: appDir,
  plugins: [...(base.plugins ?? []), previewPlugin],
  server: {
    ...base.server,
    host: "127.0.0.1",
    port: 5198,
    strictPort: true,
    fs: { strict: true, allow: [repositoryDir] },
    proxy: { "/workspace-api": { target: "http://127.0.0.1:5199", rewrite: (value: string) => value.replace(/^\/workspace-api/, "") } },
  },
}
